  ('ai:ai-batch-04:c07d1e913277','LIFE_IN_UK'::public.cefr_level,'reading','Where is Skara Brae, the best-preserved prehistoric village in northern Europe?',array['Anglesey','Cornwall','the Isle of Wight','Orkney']::text[],'D','Handbook ch. 3 (A long and illustrious history): Skara Brae on Orkney, off the north coast of Scotland, is the best-preserved prehistoric village in northern Europe.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2a1ac7b57284','LIFE_IN_UK'::public.cefr_level,'reading','In which English county does Stonehenge stand?',array['Wiltshire','Somerset','Kent','Dorset']::text[],'A','Handbook ch. 3 (A long and illustrious history): Stonehenge, a monument built during the Stone Age, still stands in the English county of Wiltshire.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:45c437ab252c','LIFE_IN_UK'::public.cefr_level,'reading','Who were the first people to live in Britain?',array['Hunter-gatherers of the Stone Age','Anglo-Saxon farmers','Roman soldiers and settlers','Viking traders from Denmark']::text[],'A','Handbook ch. 3 (A long and illustrious history): The first people to live in Britain were hunter-gatherers, in what we call the Stone Age.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:649c948dad27','LIFE_IN_UK'::public.cefr_level,'reading','About how long ago did Britain become separated from the continent of Europe?',array['50,000 years ago','10,000 years ago','2,000 years ago','4,000 years ago']::text[],'B','Handbook ch. 3 (A long and illustrious history): Britain was connected to the continent by a land bridge; it became permanently separated about 10,000 years ago.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:36856bd343eb','LIFE_IN_UK'::public.cefr_level,'reading','Which famous Iron Age hill fort can still be seen in Dorset?',array['Maiden Castle','Caernarvon Castle','Housesteads','Edinburgh Castle']::text[],'A','Handbook ch. 3 (A long and illustrious history): Iron Age people built hill forts; one of the most impressive, Maiden Castle, can still be seen in Dorset.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:55043166272b','LIFE_IN_UK'::public.cefr_level,'reading','Which family of languages was spoken by people in Britain during the Iron Age?',array['Norse','Celtic','Norman French','Latin']::text[],'B','Handbook ch. 3 (A long and illustrious history): People in the Iron Age spoke languages belonging to the Celtic language family; related languages are still spoken in parts of Wales, Scotland and Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1a8b3bd57832','LIFE_IN_UK'::public.cefr_level,'reading','Who led an unsuccessful Roman invasion of Britain in 55 BC?',array['Emperor Augustus','Julius Caesar','Emperor Hadrian','Emperor Claudius']::text[],'B','Handbook ch. 3 (A long and illustrious history): Julius Caesar led a Roman invasion of Britain in 55 BC; it was unsuccessful.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bb712b8b35e5','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the Roman Emperor Claudius lead the invasion that began Roman rule in Britain?',array['AD 789','AD 410','AD 43','55 BC']::text[],'C','Handbook ch. 3 (A long and illustrious history): For nearly 100 years after 55 BC Britain was free of Romans; then Emperor Claudius led an invasion in AD 43.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:46e7b00f76db','LIFE_IN_UK'::public.cefr_level,'reading','Boudicca, who fought against the Romans, was queen of which tribe?',array['The Iceni','The Picts','The Jutes','The Saxons']::text[],'A','Handbook ch. 3 (A long and illustrious history): Boudicca, queen of the Iceni in what is now eastern England, fought against the Romans.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:691ceee049f0','LIFE_IN_UK'::public.cefr_level,'reading','Why did Emperor Hadrian build a wall in the north of England?',array['To mark the border with Wales','To protect London from the Saxons','To keep out the Picts','To keep out the Vikings']::text[],'C','Handbook ch. 3 (A long and illustrious history): Parts of what is now Scotland were never conquered by the Romans, and Hadrian built a wall to keep out the Picts (ancestors of the Scottish people).',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bce9ce0f1198','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO places are popular sites to visit along Hadrian''s Wall?',array['Caernarvon and Conwy','Skara Brae and Maiden Castle','Sutton Hoo and Iona','Housesteads and Vindolanda']::text[],'D','Handbook ch. 3 (A long and illustrious history): Parts of Hadrian''s Wall, including the forts of Housesteads and Vindolanda, can still be seen; it is a UNESCO World Heritage Site.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6cedaac1f67b','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the Roman army leave Britain?',array['AD 1066','AD 410','AD 43','AD 600']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Roman army left Britain in AD 410 to defend other parts of the Roman Empire and never returned.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:107f87428977','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO things did the Romans bring to Britain?',array['Castles and stained glass windows','Roads and public buildings','The parliament and common law courts','The printing press and newspapers']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Romans built roads and public buildings, created a structure of law and introduced new plants and animals.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:00f551cc4cbb','LIFE_IN_UK'::public.cefr_level,'reading','Which tribes invaded Britain after the Romans left?',array['The Jutes, Angles and Saxons','The Picts, Scots and Celts','The Iceni, Huguenots and Flemish','The Normans, Danes and Franks']::text[],'A','Handbook ch. 3 (A long and illustrious history): After the Romans left, Britain was invaded by tribes from northern Europe: the Jutes, the Angles and the Saxons.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2a144db6b78c','LIFE_IN_UK'::public.cefr_level,'reading','What was found at Sutton Hoo in Suffolk?',array['A Viking longship and its crew','The remains of a Roman fort','The burial ship of an Anglo-Saxon king','A Stone Age village']::text[],'C','Handbook ch. 3 (A long and illustrious history): An Anglo-Saxon king was buried with treasure and armour in a ship at Sutton Hoo in Suffolk.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:992c9eeee23b','LIFE_IN_UK'::public.cefr_level,'reading','Who founded a monastery on the island of Iona, off the coast of Scotland?',array['St Augustine','St David','St Columba','St Patrick']::text[],'C','Handbook ch. 3 (A long and illustrious history): Missionaries came to Britain to spread Christianity; St Columba founded a monastery on Iona.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1b518c891492','LIFE_IN_UK'::public.cefr_level,'reading','Who became the first Archbishop of Canterbury?',array['St Andrew','St Augustine','Thomas Cranmer','St Columba']::text[],'B','Handbook ch. 3 (A long and illustrious history): St Augustine led missionaries from Rome who spread Christianity in the south; he became the first Archbishop of Canterbury.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:70c602ab9f07','LIFE_IN_UK'::public.cefr_level,'reading','From which countries did the Vikings come?',array['France and Spain','Denmark and Norway','Germany and the Netherlands','Italy and Greece']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Vikings came from Denmark and Norway.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9774fd7c4e50','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the Vikings first visit Britain to raid coastal towns?',array['AD 410','AD 43','AD 1066','AD 789']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Vikings first visited Britain in AD 789 to raid coastal towns and take away goods and slaves.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:892c8e903abe','LIFE_IN_UK'::public.cefr_level,'reading','Which Anglo-Saxon king united the kingdoms and defeated the Vikings?',array['Alfred the Great','Harold','Kenneth MacAlpin','Cnut']::text[],'A','Handbook ch. 3 (A long and illustrious history): The Anglo-Saxon kingdoms in England united under King Alfred the Great, who defeated the Vikings.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:adb710b9393f','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO English place names come from the Viking languages?',array['Grimsby and Scunthorpe','Stratford and Oxford','Canterbury and Winchester','Bosworth and Hastings']::text[],'A','Handbook ch. 3 (A long and illustrious history): Many place names, such as Grimsby and Scunthorpe, come from the Viking languages.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6b3d05a67a41','LIFE_IN_UK'::public.cefr_level,'reading','Under which king did the people in the north unite, so that the word ''Scotland'' came into use?',array['Robert the Bruce','Alfred the Great','James VI','Kenneth MacAlpin']::text[],'D','Handbook ch. 3 (A long and illustrious history): The threat of Viking attack encouraged people in the north to unite under one king, Kenneth MacAlpin, and the term Scotland began to be used.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:cb3602ab74c5','LIFE_IN_UK'::public.cefr_level,'reading','Who won the Battle of Hastings in 1066?',array['King Harold','Alfred the Great','William, Duke of Normandy','Robert the Bruce']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1066 William, Duke of Normandy, defeated Harold, the Saxon king of England, at the Battle of Hastings.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4ed91d991488','LIFE_IN_UK'::public.cefr_level,'reading','What does the Bayeux Tapestry show?',array['The defeat of the Spanish Armada','The coronation of Elizabeth I','The Norman invasion of 1066','The Battle of Bannockburn']::text[],'C','Handbook ch. 3 (A long and illustrious history): The Battle of Hastings is commemorated in a great piece of embroidery known as the Bayeux Tapestry, which can still be seen in France.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9f8f9401a5b3','LIFE_IN_UK'::public.cefr_level,'reading','What was the Domesday Book?',array['The first English Bible','A list of laws agreed by King John','A collection of Norman poems','A record of towns, villages, land and animals']::text[],'D','Handbook ch. 3 (A long and illustrious history): William sent people all over England to draw up lists of towns and villages, who lived there, who owned the land and what animals they owned; this was the Domesday Book.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:fc6e9f88f03b','LIFE_IN_UK'::public.cefr_level,'reading','What is the Norman Conquest of 1066 remembered as?',array['The end of the Wars of the Roses','The first Viking raid on England','The start of the Hundred Years War','The last successful foreign invasion of England']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Norman Conquest was the last successful foreign invasion of England and led to many changes in government and social structures.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:808b44a0c46a','LIFE_IN_UK'::public.cefr_level,'reading','Which king conquered Wales and built castles such as Conwy and Caernarvon?',array['Henry V','Henry VIII','William I','Edward I']::text[],'D','Handbook ch. 3 (A long and illustrious history): In 1284 King Edward I of England introduced the Statute of Rhuddlan, which annexed Wales to the Crown; huge castles, including Conwy and Caernarvon, were built to maintain his power.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:443bd3c70380','LIFE_IN_UK'::public.cefr_level,'reading','Who defeated the English at the Battle of Bannockburn in 1314?',array['Kenneth MacAlpin','James IV','Robert the Bruce','William Wallace']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1314 the Scottish, led by Robert the Bruce, defeated the English at the Battle of Bannockburn, and Scotland remained unconquered.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5813b75f3315','LIFE_IN_UK'::public.cefr_level,'reading','When the English first went to Ireland in the Middle Ages, which area did they control?',array['Ulster in the north','The Pale, around Dublin','Cork and the south coast','The whole island']::text[],'B','Handbook ch. 3 (A long and illustrious history): In the Middle Ages the English controlled an area of Ireland known as the Pale, around Dublin.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:3d4e18fc5ea1','LIFE_IN_UK'::public.cefr_level,'reading','How long did the so-called Hundred Years War with France actually last?',array['116 years','84 years','99 years','100 years']::text[],'A','Handbook ch. 3 (A long and illustrious history): English kings fought a long war with France called the Hundred Years War, even though it actually lasted 116 years.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7617b58cd083','LIFE_IN_UK'::public.cefr_level,'reading','Which king led the English to victory at the Battle of Agincourt in 1415?',array['Edward I','Richard III','Henry VII','Henry V']::text[],'D','Handbook ch. 3 (A long and illustrious history): One of the most famous battles of the Hundred Years War was the Battle of Agincourt in 1415, where King Henry V''s vastly outnumbered English army defeated the French.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bfd2c3fb94c5','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the Black Death come to Britain?',array['1485','1665','1348','1066']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1348 a disease, probably a form of plague, came to Britain; this was known as the Black Death.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9e4070301d47','LIFE_IN_UK'::public.cefr_level,'reading','What proportion of the population of England died in the Black Death?',array['One half','Two thirds','One third','One tenth']::text[],'C','Handbook ch. 3 (A long and illustrious history): One third of the population of England died in the Black Death, and a similar proportion in Scotland and Wales.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8133afb58f77','LIFE_IN_UK'::public.cefr_level,'reading','In which year was the Magna Carta agreed?',array['1314','1215','1066','1485']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Magna Carta, meaning the Great Charter, was agreed in 1215.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7a8f693e7c27','LIFE_IN_UK'::public.cefr_level,'reading','What important idea did the Magna Carta establish?',array['Parliament must meet every year','The Church was free from the Pope','Everyone had the right to vote','The king was subject to the law']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Magna Carta established the idea that even the king was subject to the law.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4872ed12901e','LIFE_IN_UK'::public.cefr_level,'reading','Who wrote The Canterbury Tales?',array['William Shakespeare','Geoffrey Chaucer','John Barbour','William Caxton']::text[],'B','Handbook ch. 3 (A long and illustrious history): Geoffrey Chaucer wrote a series of poems in English about people on a pilgrimage to Canterbury, called The Canterbury Tales.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:abc3ea2d0b9e','LIFE_IN_UK'::public.cefr_level,'reading','Who was the first person in England to print books using a printing press?',array['Geoffrey Chaucer','Samuel Pepys','William Caxton','Thomas Cranmer']::text[],'C','Handbook ch. 3 (A long and illustrious history): William Caxton was the first person in England to print books using a printing press; The Canterbury Tales was one of the first books printed.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8f3d80d4112a','LIFE_IN_UK'::public.cefr_level,'reading','Which two houses fought each other in the Wars of the Roses?',array['Tudor and Stuart','Normandy and Anjou','Lancaster and York','Hanover and Orange']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1455 a civil war, the Wars of the Roses, began to decide who should be king of England, fought between the House of Lancaster and the House of York.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:3f9a7e250f08','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the Battle of Bosworth Field end the Wars of the Roses?',array['1415','1588','1455','1485']::text[],'D','Handbook ch. 3 (A long and illustrious history): The war ended with the Battle of Bosworth Field in 1485.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ced88be7701d','LIFE_IN_UK'::public.cefr_level,'reading','Which king was killed at the Battle of Bosworth Field?',array['Henry VII','Richard III','Henry VI','Edward IV']::text[],'B','Handbook ch. 3 (A long and illustrious history): King Richard III of the House of York was killed in the Battle of Bosworth Field.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:16132fe8944f','LIFE_IN_UK'::public.cefr_level,'reading','Which of Henry VIII''s wives was a Spanish princess?',array['Anne Boleyn','Catherine of Aragon','Jane Seymour','Catherine Parr']::text[],'B','Handbook ch. 3 (A long and illustrious history): Catherine of Aragon was a Spanish princess; when she failed to give him a son, Henry wanted a divorce.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2d7e28ce5730','LIFE_IN_UK'::public.cefr_level,'reading','Which wife of Henry VIII was the mother of Elizabeth I?',array['Jane Seymour','Catherine Howard','Anne of Cleves','Anne Boleyn']::text[],'D','Handbook ch. 3 (A long and illustrious history): Anne Boleyn was English and had one daughter, Elizabeth; she was executed at the Tower of London.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b4ac9d7adf81','LIFE_IN_UK'::public.cefr_level,'reading','Which wife of Henry VIII gave birth to his son Edward?',array['Anne Boleyn','Jane Seymour','Catherine Parr','Catherine of Aragon']::text[],'B','Handbook ch. 3 (A long and illustrious history): Henry married Jane Seymour, who gave him the son he wanted, Edward; she died shortly after the birth.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:176166c1d406','LIFE_IN_UK'::public.cefr_level,'reading','Which wife of Henry VIII outlived him?',array['Catherine Howard','Jane Seymour','Anne Boleyn','Catherine Parr']::text[],'D','Handbook ch. 3 (A long and illustrious history): Catherine Parr was a widow who married Henry late in his life; she survived him and married again but died soon after.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2e86fff892c0','LIFE_IN_UK'::public.cefr_level,'reading','Why did Henry VIII establish the Church of England?',array['The Pope refused to let him divorce','The Spanish king asked him to','He wanted to become a Catholic priest','Parliament ordered him to do so']::text[],'A','Handbook ch. 3 (A long and illustrious history): To divorce his first wife Henry needed the Pope''s approval; when the Pope refused, Henry established the Church of England, in which the king had the power to appoint bishops.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ec6dc03836cc','LIFE_IN_UK'::public.cefr_level,'reading','Which Act formally united Wales with England during the reign of Henry VIII?',array['The Statute of Rhuddlan','The Act for the Government of Wales','The Act of Union','The Bill of Rights']::text[],'B','Handbook ch. 3 (A long and illustrious history): During the reign of Henry VIII, Wales became formally united with England by the Act for the Government of Wales.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d61bb521879e','LIFE_IN_UK'::public.cefr_level,'reading','Which book was written during the reign of Edward VI and is still used in some Church of England services?',array['The King James Bible','The Book of Common Prayer','The Canterbury Tales','The Domesday Book']::text[],'B','Handbook ch. 3 (A long and illustrious history): Edward VI was strongly Protestant; during his reign the Book of Common Prayer was written, a version of which is still used in some Church of England churches.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:18de5f85cc53','LIFE_IN_UK'::public.cefr_level,'reading','Which monarch, a devout Catholic, persecuted Protestants and became known as ''Bloody Mary''?',array['Mary Queen of Scots','Mary II','Mary I','Mary of Guise']::text[],'C','Handbook ch. 3 (A long and illustrious history): Edward VI was followed by his half-sister Mary, a devout Catholic who persecuted Protestants; she became known as ''Bloody Mary''.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a4a552366090','LIFE_IN_UK'::public.cefr_level,'reading','In which year did England defeat the Spanish Armada?',array['1588','1603','1666','1485']::text[],'A','Handbook ch. 3 (A long and illustrious history): Elizabeth I became one of the most popular monarchs, particularly after the defeat of the Spanish Armada in 1588.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:64b3a55b6096','LIFE_IN_UK'::public.cefr_level,'reading','What was Sir Francis Drake''s ship called?',array['The Mary Rose','The Golden Hind','The Victory','The Mayflower']::text[],'B','Handbook ch. 3 (A long and illustrious history): Sir Francis Drake, one of the commanders against the Armada, was one of the founders of England''s naval tradition; his ship, the Golden Hind, was one of the first to sail around the world.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:aef7c8f8d957','LIFE_IN_UK'::public.cefr_level,'reading','Where was William Shakespeare born?',array['Stratford-upon-Avon','Oxford','London','Canterbury']::text[],'A','Handbook ch. 3 (A long and illustrious history): William Shakespeare was born in Stratford-upon-Avon, England, in 1564.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7c3da3b1982b','LIFE_IN_UK'::public.cefr_level,'reading','Which famous line comes from Shakespeare?',array['Scots wha hae','To be or not to be','Rule, Britannia','We shall fight on the beaches']::text[],'B','Handbook ch. 3 (A long and illustrious history): Lines from Shakespeare''s plays are still quoted, such as ''To be or not to be'' and ''Once more unto the breach''.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7be0f8e9cbd6','LIFE_IN_UK'::public.cefr_level,'reading','When Elizabeth I died in 1603, who became King of England?',array['William of Orange','James VI of Scotland','Mary, Queen of Scots','Charles I']::text[],'B','Handbook ch. 3 (A long and illustrious history): Elizabeth I never married and had no children; when she died in 1603 her heir was her cousin James VI of Scotland, who also became James I of England, Wales and Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:95ee2e153542','LIFE_IN_UK'::public.cefr_level,'reading','Which translation of the Bible was produced under James I?',array['The Book of Common Prayer','The Domesday Bible','The Geneva Version','The King James Version']::text[],'D','Handbook ch. 3 (A long and illustrious history): During James I''s reign a new translation of the Bible into English, the ''King James Version'' or ''Authorised Version'', was made; it is still used in many Protestant churches today.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4ed642cc55fa','LIFE_IN_UK'::public.cefr_level,'reading','What were the ''plantations'' in Ireland under James I?',array['Settlements of Protestants on land in Ulster','Catholic monasteries in Dublin','Farms growing tobacco for export','Royal forests for hunting']::text[],'A','Handbook ch. 3 (A long and illustrious history): Under James I, many Protestant settlers from England and Scotland were given land in Ulster, taking it from Catholic landholders; these settlements were known as plantations.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d19c4d48e366','LIFE_IN_UK'::public.cefr_level,'reading','What did James I and his son Charles I believe in?',array['A republic run by Parliament','The ''Divine Right of Kings''','Votes for all adult men','A Catholic Church led by the Pope']::text[],'B','Handbook ch. 3 (A long and illustrious history): James I and his son Charles I believed in the ''Divine Right of Kings'': the idea that the king was directly appointed by God to rule.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:eb522c3ec5b9','LIFE_IN_UK'::public.cefr_level,'reading','What were supporters of the king called in the English Civil War?',array['Jacobites','Roundheads','Whigs','Cavaliers']::text[],'D','Handbook ch. 3 (A long and illustrious history): Those who supported the king were called Cavaliers; those who supported Parliament were called Roundheads.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9382bf424cd6','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO battles did Parliament''s army win against Charles I?',array['Bannockburn and Agincourt','Hastings and Bosworth','Culloden and the Boyne','Marston Moor and Naseby']::text[],'D','Handbook ch. 3 (A long and illustrious history): Charles I''s army was defeated by Parliament at the Battles of Marston Moor and Naseby; by 1646 Parliament had won the war.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:120e1e25d751','LIFE_IN_UK'::public.cefr_level,'reading','In which year was Charles I executed?',array['1649','1688','1642','1660']::text[],'A','Handbook ch. 3 (A long and illustrious history): Charles I was executed in 1649 after refusing to make an agreement with Parliament.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c2b6415429a2','LIFE_IN_UK'::public.cefr_level,'reading','What title did Oliver Cromwell take as leader of the republic?',array['Prime Minister','Lord Protector','King of England','Lord Chancellor']::text[],'B','Handbook ch. 3 (A long and illustrious history): With no king, England declared itself a republic called the Commonwealth; Oliver Cromwell was given the title of Lord Protector and ruled until his death in 1658.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1b3d4e661b48','LIFE_IN_UK'::public.cefr_level,'reading','In which year was the monarchy restored with Charles II?',array['1688','1666','1649','1660']::text[],'D','Handbook ch. 3 (A long and illustrious history): In May 1660 Parliament invited Charles II to come back from exile in the Netherlands; this period is called the Restoration.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:3bb6403d77ed','LIFE_IN_UK'::public.cefr_level,'reading','Which scientific society, the oldest surviving one in the world, was formed during the reign of Charles II?',array['The British Academy','The Royal College of Science','The Royal Institution','The Royal Society']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Royal Society was formed to promote ''natural knowledge''; it is the oldest surviving scientific society in the world.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b8612ee9e3e4','LIFE_IN_UK'::public.cefr_level,'reading','Who designed the new St Paul''s Cathedral after the Great Fire of London?',array['Isambard Kingdom Brunel','Sir Christopher Wren','Inigo Jones','Robert Adam']::text[],'B','Handbook ch. 3 (A long and illustrious history): A great fire destroyed much of London in 1666, including many churches; St Paul''s Cathedral was rebuilt to a design by Sir Christopher Wren.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2299e838baeb','LIFE_IN_UK'::public.cefr_level,'reading','What did the Habeas Corpus Act of 1679 guarantee?',array['That Parliament would meet every three years','That every prisoner has a right to a court hearing','That every man could vote','That the monarch must be Protestant']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Habeas Corpus Act became law in 1679; it guaranteed that no one could be held prisoner unlawfully, as every prisoner has a right to a court hearing.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c7e674b35ca3','LIFE_IN_UK'::public.cefr_level,'reading','Who was invited to invade England in 1688 in what became known as the Glorious Revolution?',array['George I','Charles II','William of Orange','James Stuart']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1688 important Protestants asked William of Orange, the Protestant ruler of the Netherlands and husband of James II''s daughter Mary, to invade England.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:576a00c127f5','LIFE_IN_UK'::public.cefr_level,'reading','Why is the revolution of 1688 called ''Glorious''?',array['It made England a republic','It gave all men the right to vote','There was no fighting in England','It ended the Hundred Years War']::text[],'C','Handbook ch. 3 (A long and illustrious history): William''s invasion was called the Glorious Revolution because there was no fighting in England and because it guaranteed the power of Parliament.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e673b818fab8','LIFE_IN_UK'::public.cefr_level,'reading','Which document of 1689 confirmed the rights of Parliament and the limits of the king''s power?',array['The Act of Union','The Magna Carta','The Habeas Corpus Act','The Bill of Rights']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Bill of Rights, 1689, confirmed the rights of Parliament and the limits of the king''s power.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:102a89b3a631','LIFE_IN_UK'::public.cefr_level,'reading','Who were the Huguenots who came to Britain between 1680 and 1720?',array['French Protestants','German merchants','Spanish Catholics','Dutch engineers']::text[],'A','Handbook ch. 3 (A long and illustrious history): Between 1680 and 1720 many refugees called Huguenots came from France; they were Protestants who had been persecuted for their religion.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bbd4da043912','LIFE_IN_UK'::public.cefr_level,'reading','What was created by the Act of Union of 1707?',array['The Kingdom of Great Britain','The United Kingdom of Great Britain and Ireland','The Church of England','The Commonwealth']::text[],'A','Handbook ch. 3 (A long and illustrious history): The Act of Union, known as the Treaty of Union in Scotland, was agreed in 1707, creating the Kingdom of Great Britain.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:cfb7799d504a','LIFE_IN_UK'::public.cefr_level,'reading','After Queen Anne died in 1714, who did Parliament choose as king?',array['Charles III','James Stuart','William III','George I']::text[],'D','Handbook ch. 3 (A long and illustrious history): Queen Anne had no surviving children; Parliament chose a German, George I, to be the next king, because he was Anne''s nearest Protestant relative.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b50d57d6627e','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Henry VII strengthened the central administration of England and reduced the power of the nobles.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Henry VII wanted England to remain peaceful and his position to be secure, so he strengthened central administration and reduced the power of the nobles.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:daf629b4f188','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: When the Vikings first came to Britain, they came to settle peacefully as farmers.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Vikings first visited Britain in AD 789 to raid coastal towns and take away goods and slaves; later some stayed and settled.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:889a43594a00','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The first farmers in Britain probably came from south-east Europe.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): The first farmers arrived about 6,000 years ago, probably from south-east Europe.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e81891f238b4','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Stonehenge is in Scotland.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): Stonehenge stands in the English county of Wiltshire; Skara Brae is the prehistoric village on Orkney, Scotland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b2d4dc634d68','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Romans conquered all of what is now Scotland.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): Parts of what is now Scotland were never conquered by the Romans; Hadrian built a wall to keep out the Picts.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e71075630386','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Vikings who settled in England lived mainly in the south and west.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): Many Vikings stayed in the east and north of England, in an area known as the Danelaw.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d3a6e08e2e15','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Harold was the Saxon king of England who was killed at the Battle of Hastings.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): In 1066 William of Normandy defeated Harold, the Saxon king of England, at the Battle of Hastings.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f72f00017b71','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Normans conquered Scotland after the Battle of Hastings.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Normans did not conquer Scotland; the Battle of Hastings made William king of England.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:566f265f730c','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Norman French and Anglo-Saxon gradually combined to form the English language.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): After the Norman Conquest, Norman French and Anglo-Saxon gradually blended to become one language, known as English.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:acb84d7c5c0f','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Black Death led to a shortage of workers and the growth of new social classes.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): After the Black Death there were fewer people; labour shortages led to new social classes, including owners of large areas of land (later called the gentry).',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ed677cc984a5','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Magna Carta gave every adult the right to vote.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Magna Carta restricted the king''s power and showed that even the king was subject to the law; only a small part of the population could vote for centuries afterwards.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8ef9dbdf6d5b','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: In the Middle Ages, judges in England developed ''common law'' based on precedent and tradition.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Judges developed ''common law'' through a process of precedence (following previous decisions) and tradition.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:50e258e17124','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The House of Lancaster''s symbol was a white rose.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The symbol of Lancaster was a red rose and the symbol of York was a white rose.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:74eedd625cc9','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Tudor rose combines the red rose of Lancaster and the white rose of York.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Henry VII''s marriage united the families; the red and white Tudor rose became the symbol of the House of Tudor.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d549459cc11d','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Catherine Howard was a cousin of Anne Boleyn and was executed.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Catherine Howard was a cousin of Anne Boleyn; she was accused of taking lovers and was executed.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4d42e2b5073c','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Elizabeth I re-established the Church of England.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Elizabeth I was a Protestant and re-established the Church of England as the official Church.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:011d1c5066d0','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Mary, Queen of Scots, was executed on the orders of Elizabeth I.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Elizabeth I held Mary prisoner for 20 years and later executed her, accusing her of plotting to overthrow her.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8188acc2eee9','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: James I of England had already been King of Scotland before 1603.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): James VI of Scotland became James I of England, Wales and Ireland when Elizabeth I died in 1603.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:74158e170303','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The English Civil War began in 1688.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Civil War began in 1642, when Charles I tried to arrest five parliamentary leaders, and civil war began between the king and Parliament.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:475cb6588dca','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Great Fire of London happened in 1666.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): A great fire destroyed much of London in 1666, including many churches.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c97b530eb664','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: James II was a Protestant king.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): James II was a Roman Catholic; his daughters Mary and Anne were Protestants.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9562bc3e80f8','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: William III defeated James II at the Battle of the Boyne in Ireland in 1690.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): James II tried to regain the throne with an army in Ireland; William defeated him at the Battle of the Boyne in 1690, an event still celebrated by some in Northern Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4d965cc324eb','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: After the Act of Union of 1707, Scotland kept its own legal and education systems.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Under the Act of Union Scotland was no longer an independent country, but it kept its own legal and education systems and Presbyterian Church.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9340bd791d66','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: From 1695, newspapers in Britain needed a government licence.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): From 1695 newspapers were allowed to operate without a government licence, and more and more were published.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f036897e15ab','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO disasters struck London in 1665 and 1666?',array['The Black Death and the Great Flood','The Armada and the Gunpowder Plot','The Civil War and the Restoration','The Great Plague and the Great Fire']::text[],'D','Handbook ch. 3 (A long and illustrious history): London suffered the Great Plague in 1665 and a great fire in 1666 that destroyed much of the city.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:78752e4b9306','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO of Henry VIII''s wives did he divorce?',array['Anne Boleyn and Jane Seymour','Catherine of Aragon and Anne of Cleves','Catherine Howard and Catherine Parr','Jane Seymour and Catherine Parr']::text[],'B','Handbook ch. 3 (A long and illustrious history): Henry divorced Catherine of Aragon when she did not give him a son, and divorced Anne of Cleves soon after their political marriage.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f36ffe4c704a','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO of Henry VIII''s wives were executed?',array['Jane Seymour and Catherine Parr','Anne Boleyn and Catherine Howard','Anne of Cleves and Catherine Parr','Catherine of Aragon and Jane Seymour']::text[],'B','Handbook ch. 3 (A long and illustrious history): Anne Boleyn and Catherine Howard were both executed; Catherine of Aragon and Anne of Cleves were divorced, Jane Seymour died after childbirth and Catherine Parr survived Henry.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f0350860ed31','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO political groups developed in Parliament after the Glorious Revolution?',array['Labour and the Liberals','The Jacobites and the Huguenots','The Cavaliers and the Roundheads','The Whigs and the Tories']::text[],'D','Handbook ch. 3 (A long and illustrious history): Two main groups developed in Parliament, the Whigs and the Tories; the modern Conservative Party is still sometimes referred to as the Tories.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:65561fcbb050','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO cathedrals are examples of the great buildings of the Middle Ages?',array['Liverpool Cathedral and Coventry Cathedral','Truro Cathedral and Guildford Cathedral','St Paul''s Cathedral and Westminster Cathedral','Lincoln Cathedral and York Minster']::text[],'D','Handbook ch. 3 (A long and illustrious history): In the Middle Ages great cathedrals such as Lincoln Cathedral and York Minster were built, many with stained glass windows.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:fc3111d5f163','LIFE_IN_UK'::public.cefr_level,'reading','Who is generally regarded as the first Prime Minister of Great Britain?',array['Sir Robert Walpole','William Pitt the Younger','Sir Robert Peel','Duke of Wellington']::text[],'A','Handbook ch. 3 (A long and illustrious history): Robert Walpole led the government from 1721 to 1742 and is regarded as the first Prime Minister.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1fa7379b3ba7','LIFE_IN_UK'::public.cefr_level,'reading','In 1745 Charles Edward Stuart tried to take the throne. By what name is he popularly known?',array['The Young Pretender of Wales','The Black Prince','Charles the Bold','Bonnie Prince Charlie']::text[],'D','Handbook ch. 3 (A long and illustrious history): Charles Edward Stuart, grandson of James II, became known as Bonnie Prince Charlie.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2414befcfa4c','LIFE_IN_UK'::public.cefr_level,'reading','At which battle was Bonnie Prince Charlie defeated in 1746?',array['Bosworth Field','Culloden','the Boyne','Bannockburn']::text[],'B','Handbook ch. 3 (A long and illustrious history): Charles Edward Stuart''s army was defeated at the Battle of Culloden in 1746, after which he escaped back to Europe.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:81bd2938fd39','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: After his defeat at Culloden, Bonnie Prince Charlie was crowned King of Scotland.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): Bonnie Prince Charlie was defeated at Culloden in 1746 and escaped back to Europe; he never became king.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ea3c5f472ac6','LIFE_IN_UK'::public.cefr_level,'reading','What happened during the Highland Clearances?',array['Coal mines were closed across the Highlands','Castles were demolished on the king''s orders','Landlords destroyed small farms to make space for sheep and cattle','Forests were cut down to build warships']::text[],'C','Handbook ch. 3 (A long and illustrious history): In the Highland Clearances many Scottish landlords destroyed individual small farms (crofts) to make space for large flocks of sheep and herds of cattle.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a88b44c65e98','LIFE_IN_UK'::public.cefr_level,'reading','Which Scottish poet, known as ''The Bard'', wrote ''Auld Lang Syne''?',array['Robert Louis Stevenson','Walter Scott','Robert Burns','Dylan Thomas']::text[],'C','Handbook ch. 3 (A long and illustrious history): Robert Burns (1759–96) wrote in Scots, English and a mixture of both; his best-known work includes ''Auld Lang Syne''.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a194e61c6330','LIFE_IN_UK'::public.cefr_level,'reading','During the Enlightenment, Adam Smith developed important ideas in which field?',array['Medicine','Economics','Architecture','Astronomy']::text[],'B','Handbook ch. 3 (A long and illustrious history): Adam Smith, a figure of the Scottish Enlightenment, developed ideas about economics which are still referred to today.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:543204f88bd3','LIFE_IN_UK'::public.cefr_level,'reading','Which Enlightenment thinker''s ideas about human nature continue to influence philosophers?',array['Adam Smith','John Logie Baird','David Hume','Isaac Newton']::text[],'C','Handbook ch. 3 (A long and illustrious history): David Hume''s ideas about human nature continue to influence philosophers.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bd59f84ceda4','LIFE_IN_UK'::public.cefr_level,'reading','James Watt''s scientific work, which helped the Industrial Revolution, was about what?',array['Radio waves','Penicillin','Electricity','Steam power']::text[],'D','Handbook ch. 3 (A long and illustrious history): James Watt''s work on steam power helped the progress of the Industrial Revolution.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:70b64c0ca6e4','LIFE_IN_UK'::public.cefr_level,'reading','What did the Bessemer process make possible?',array['The mass production of cotton cloth','The mass production of steel','Cheap printing of newspapers','Faster sailing ships']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Bessemer process for the mass production of steel led to the development of the shipbuilding and railway industries.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:102784d60cdb','LIFE_IN_UK'::public.cefr_level,'reading','Why were canals built during the Industrial Revolution?',array['To protect towns from flooding','To supply drinking water to London','To link factories to towns, cities and ports','To irrigate farmland']::text[],'C','Handbook ch. 3 (A long and illustrious history): Canals were built to link the factories to towns and cities and to the ports, particularly in the new industrial areas of the middle and north of England.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7e0a80c8e528','LIFE_IN_UK'::public.cefr_level,'reading','Sake Dean Mahomet opened Britain''s first curry house in London in 1810. What was it called?',array['The Bengal Dining Club','The Bombay Tea Room','The Taj Supper House','The Hindoostane Coffee House']::text[],'D','Handbook ch. 3 (A long and illustrious history): Sake Dean Mahomet opened the Hindoostane Coffee House in George Street, London, in 1810.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7a156e6f8997','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Sake Dean Mahomet introduced ''shampooing'', a type of Indian head massage, to Britain.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): Sake Dean Mahomet and his wife introduced shampooing to Britain and he was appointed ''Shampooing Surgeon'' to Kings George IV and William IV.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d6da0960c149','LIFE_IN_UK'::public.cefr_level,'reading','Which group set up the first formal anti-slavery groups in Britain in the late 1700s?',array['The Chartists','The Puritans','The Huguenots','The Quakers']::text[],'D','Handbook ch. 3 (A long and illustrious history): The first formal anti-slavery groups were set up by the Quakers in the late 1700s.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7a4c80b1d9cb','LIFE_IN_UK'::public.cefr_level,'reading','Which evangelical Christian and MP played an important part in ending the slave trade?',array['William Pitt the Elder','Robert Walpole','William Wilberforce','Edmund Burke']::text[],'C','Handbook ch. 3 (A long and illustrious history): William Wilberforce, an evangelical Christian and MP, played an important part in changing the law against slavery.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c17eb6accab7','LIFE_IN_UK'::public.cefr_level,'reading','In which year did it become illegal to trade slaves in British ships or from British ports?',array['1807','1870','1776','1833']::text[],'A','Handbook ch. 3 (A long and illustrious history): In 1807 it became illegal to trade slaves in British ships or from British ports.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8ba34c73df9e','LIFE_IN_UK'::public.cefr_level,'reading','In which year was slavery abolished throughout the British Empire by the Emancipation Act?',array['1807','1833','1848','1815']::text[],'B','Handbook ch. 3 (A long and illustrious history): In 1833 the Emancipation Act abolished slavery throughout the British Empire.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b41f9ece8c6c','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: After slavery was abolished, about 2 million Indian and Chinese workers were employed to replace the freed slaves.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): After 1833, 2 million Indian and Chinese workers were employed to replace the freed slaves.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:43307c0f2d68','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the 13 American colonies declare their independence?',array['1745','1776','1801','1707']::text[],'B','Handbook ch. 3 (A long and illustrious history): The colonists declared independence in 1776; Britain recognised it in 1783.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:166e53ca06dd','LIFE_IN_UK'::public.cefr_level,'reading','In which battle of 1805 did Admiral Nelson defeat the combined French and Spanish fleets?',array['Waterloo','Trafalgar','the Somme','Culloden']::text[],'B','Handbook ch. 3 (A long and illustrious history): Nelson won the Battle of Trafalgar in 1805 but was killed in the battle.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1be435b90fa6','LIFE_IN_UK'::public.cefr_level,'reading','Who defeated Napoleon at the Battle of Waterloo in 1815?',array['Oliver Cromwell','Robert Clive','The Duke of Wellington','Admiral Nelson']::text[],'C','Handbook ch. 3 (A long and illustrious history): The Duke of Wellington defeated Napoleon at Waterloo in 1815; he later became Prime Minister.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:93b77aac71cf','LIFE_IN_UK'::public.cefr_level,'reading','The Union Flag of 1801 combines the crosses of which three patron saints?',array['St George, St Andrew and St Patrick','St George, St David and St Andrew','St George, St David and St Patrick','St David, St Patrick and St Andrew']::text[],'A','Handbook ch. 3 (A long and illustrious history): The 1801 Union Flag combines the crosses of St George, St Andrew and St Patrick, after the Act of Union with Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:00a8608ac9ab','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Welsh dragon appears on the Union Flag.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Union Flag does not include the Welsh dragon, because Wales was already united with England when the first Union Flag was created.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:88fead853db7','LIFE_IN_UK'::public.cefr_level,'reading','How old was Victoria when she became queen in 1837?',array['21','16','25','18']::text[],'D','Handbook ch. 3 (A long and illustrious history): Queen Victoria became queen in 1837 aged 18 and reigned until 1901, almost 64 years.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9001069403aa','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: By the end of the Victorian period the British Empire had fewer than 50 million people.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): By the end of the Victorian period the British Empire was the largest empire the world has ever seen, with an estimated population of more than 400 million people.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5c249aa0a410','LIFE_IN_UK'::public.cefr_level,'reading','What was one effect of the Reform Act of 1832?',array['It gave women the right to vote','It greatly increased the number of people with the right to vote','It created the Welsh Assembly','It abolished the House of Lords']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Reform Act of 1832 greatly increased the number of people with the right to vote and abolished most ''rotten'' and ''pocket'' boroughs.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:33781ea71e74','LIFE_IN_UK'::public.cefr_level,'reading','In the 1830s and 1840s, which group campaigned for further reform of voting?',array['The Jacobites','The Puritans','The Chartists','The Suffragettes']::text[],'C','Handbook ch. 3 (A long and illustrious history): In the 1830s and 1840s a group called the Chartists campaigned for reform.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5133fe8e755e','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Until 1870, a married woman kept full control of her own earnings and property.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): Until 1870 a married woman''s earnings, property and money automatically belonged to her husband; Acts of 1870 and 1882 gave wives the right to keep them.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:02d580666c66','LIFE_IN_UK'::public.cefr_level,'reading','Which campaigner, born in Manchester in 1858, set up the Women''s Social and Political Union?',array['Mary Quant','Florence Nightingale','Emmeline Pankhurst','Elizabeth Fry']::text[],'C','Handbook ch. 3 (A long and illustrious history): Emmeline Pankhurst founded the Women''s Social and Political Union in 1903; its members became known as suffragettes.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:32cae41036fb','LIFE_IN_UK'::public.cefr_level,'reading','In 1918 women gained the right to vote at what minimum age?',array['30','21','25','18']::text[],'A','Handbook ch. 3 (A long and illustrious history): In 1918 women over the age of 30 were given voting rights; in 1928 women got the vote at 21, the same as men.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a51b95cddc30','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO statements about women''s voting rights are correct?',array['Women over 30 could vote from 1918 and women over 21 from 1928','Women over 18 could vote from 1918 and women over 30 from 1928','Women over 21 could vote from 1918 and women over 18 from 1928','Women over 30 could vote from 1928 and women over 21 from 1945']::text[],'A','Handbook ch. 3 (A long and illustrious history): Women over 30 got the vote in 1918; in 1928 women received the vote at 21, the same age as men.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a1cf2a1ac707','LIFE_IN_UK'::public.cefr_level,'reading','Florence Nightingale became famous for her work in which war?',array['The First World War','The Boer War','The American War of Independence','The Crimean War']::text[],'D','Handbook ch. 3 (A long and illustrious history): In 1854 Florence Nightingale went to Turkey and treated soldiers fighting in the Crimean War.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:17c2375a845f','LIFE_IN_UK'::public.cefr_level,'reading','Florence Nightingale founded the Nightingale Training School for nurses at which hospital?',array['Royal Infirmary, Edinburgh','Great Ormond Street, London','St Thomas'' Hospital, London','Guy''s Hospital, London']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1860 she established the Nightingale Training School for nurses at St Thomas'' Hospital in London. She is regarded as the founder of modern nursing.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ddab676047af','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO projects are associated with the engineer Isambard Kingdom Brunel?',array['The Great Western Railway and the Clifton Suspension Bridge','Tower Bridge and the Severn Bridge','The Great Western Railway and the Forth Bridge','The Forth Bridge and the Channel Tunnel']::text[],'A','Handbook ch. 3 (A long and illustrious history): Brunel built the Great Western Railway, the first major railway built in Britain, and designed the Clifton Suspension Bridge in Bristol.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:108ba8b7866a','LIFE_IN_UK'::public.cefr_level,'reading','What caused the Irish famine of the mid-19th century?',array['The closure of the linen mills','A long war with France','A plague brought by ships','The potato crop failed']::text[],'D','Handbook ch. 3 (A long and illustrious history): In the mid-19th century the potato crop in Ireland failed; a million people died and about one and a half million left Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:88461452919a','LIFE_IN_UK'::public.cefr_level,'reading','Between which years was the Boer War fought in South Africa?',array['1882–1885','1914–1918','1853–1856','1899–1902']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Boer War of 1899 to 1902 made the discussions about the future of the Empire more urgent.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:0570510103e3','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The First World War ended at 11 am on 11 November 1918.',array['True','False']::text[],'A','Handbook ch. 3 (A long and illustrious history): The war ended at 11.00 am on 11 November 1918 with victory for Britain and its allies.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e9a266b00bac','LIFE_IN_UK'::public.cefr_level,'reading','During the First World War, the British suffered 60,000 casualties on the first day of which battle in 1916?',array['The Battle of Waterloo','The Battle of Britain','The Battle of Trafalgar','The Battle of the Somme']::text[],'D','Handbook ch. 3 (A long and illustrious history): In July 1916 the British attack on the Somme resulted in about 60,000 British casualties on the first day alone.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:86975d9e91e7','LIFE_IN_UK'::public.cefr_level,'reading','In 1922 Ireland was divided into two countries. How many counties in the north remained part of the UK?',array['Twelve','Four','Six','Nine']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1921 a peace treaty was signed and in 1922 Ireland became two countries; the six counties in the north remained part of the UK as Northern Ireland.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b35d0fe60714','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO phrases come from Winston Churchill''s famous wartime speeches?',array['''Blood, toil, tears and sweat'' and ''Lest we forget''','''Keep calm and carry on'' and ''We shall never surrender''','''We shall never surrender'' and ''blood, toil, tears and sweat''','''A land fit for heroes'' and ''Never had it so good''']::text[],'C','Handbook ch. 3 (A long and illustrious history): Churchill told Parliament he could offer only ''blood, toil, tears and sweat'', and declared ''we shall never surrender''.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a2d67f85c8d8','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: In 2002 the British public voted Isaac Newton the greatest Briton of all time.',array['True','False']::text[],'B','Handbook ch. 3 (A long and illustrious history): In 2002 Winston Churchill was voted the greatest Briton of all time by the British public.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5232ac3badb6','LIFE_IN_UK'::public.cefr_level,'reading','What happened at Dunkirk in 1940?',array['The RAF defeated the German air force','British troops landed to liberate France','Many civilian volunteers in small boats helped rescue over 300,000 soldiers','Germany signed its surrender']::text[],'C','Handbook ch. 3 (A long and illustrious history): In 1940 many civilian volunteers in small pleasure and fishing boats helped rescue more than 300,000 men from the beaches of Dunkirk.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ea1993374903','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO aircraft are linked with the Battle of Britain in 1940?',array['The Spitfire and Concorde','The Harrier and the Hurricane','The Spitfire and the Hurricane','Concorde and the Harrier']::text[],'C','Handbook ch. 3 (A long and illustrious history): In summer 1940 the RAF won the Battle of Britain; the key aircraft were the Spitfire and the Hurricane.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2a782e298a8e','LIFE_IN_UK'::public.cefr_level,'reading','What was ''the Blitz''?',array['The evacuation of children to the countryside','The German bombing of London and other British cities','A severe winter during the war','The British naval blockade of Germany']::text[],'B','Handbook ch. 3 (A long and illustrious history): The Blitz was the German bombing of London and other cities, such as Coventry, during the Second World War.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c357423302b5','LIFE_IN_UK'::public.cefr_level,'reading','On what date did the D-Day landings in Normandy take place?',array['1 September 1939','11 November 1918','6 June 1944','8 May 1945']::text[],'C','Handbook ch. 3 (A long and illustrious history): On 6 June 1944 allied forces landed in Normandy (D-Day).',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2ddb4fcb8801','LIFE_IN_UK'::public.cefr_level,'reading','Who discovered penicillin in 1928?',array['Francis Crick','Edward Jenner','Joseph Lister','Alexander Fleming']::text[],'D','Handbook ch. 3 (A long and illustrious history): Scottish scientist Alexander Fleming discovered penicillin in 1928; it was developed into a usable medicine by Howard Florey and Ernst Chain.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9a7a561caa34','LIFE_IN_UK'::public.cefr_level,'reading','Who was the Minister for Health when the National Health Service was established in 1948?',array['Clement Attlee','William Beveridge','Aneurin (Nye) Bevan','Rab Butler']::text[],'C','Handbook ch. 3 (A long and illustrious history): Aneurin (Nye) Bevan, Minister for Health in the Labour government, led the establishment of the NHS in 1948.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4ae21e4a1400','LIFE_IN_UK'::public.cefr_level,'reading','Which Labour Prime Minister led the government from 1945 to 1951?',array['Harold Wilson','Clement Attlee','Ramsay MacDonald','Winston Churchill']::text[],'B','Handbook ch. 3 (A long and illustrious history): Clement Attlee''s Labour government nationalised major industries and established the welfare state, including the NHS.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:37b0823b3401','LIFE_IN_UK'::public.cefr_level,'reading','The 1942 Beveridge Report identified five ''Giant Evils''. Which list is correct?',array['Want, War, Ignorance, Debt and Idleness','Hunger, War, Crime, Disease and Poverty','Want, Disease, Ignorance, Squalor and Idleness','Poverty, Crime, Squalor, Greed and Idleness']::text[],'C','Handbook ch. 3 (A long and illustrious history): William Beveridge''s report recommended that the government fight the five Giant Evils of Want, Disease, Ignorance, Squalor and Idleness.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8d6d40345730','LIFE_IN_UK'::public.cefr_level,'reading','What did the 1944 Education Act, introduced by Rab Butler, provide?',array['Compulsory Welsh lessons in schools','Free university places for all','Free school meals for every child','Free secondary education for all in England and Wales']::text[],'D','Handbook ch. 3 (A long and illustrious history): The Education Act 1944 (the ''Butler Act'') introduced free secondary education in England and Wales.',array['life_in_uk','lituk_history']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
