  ('ai:ai-batch-04:bbbc5661e651','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO fashion designers are British?',array['Giorgio Armani and Mary Quant','Coco Chanel and Mary Quant','Mary Quant and Vivienne Westwood','Vivienne Westwood and Christian Dior']::text[],'C','Handbook ch. 4 (A modern, thriving society): Famous British designers include Mary Quant, Vivienne Westwood, Alexander McQueen and Thomas Burberry.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e00abfde60c4','LIFE_IN_UK'::public.cefr_level,'reading','Which dish is traditionally associated with Scotland?',array['Haggis','Welsh cakes','Ulster fry','Roast beef with Yorkshire pudding']::text[],'A','Handbook ch. 4 (A modern, thriving society): Haggis is a sheep''s stomach stuffed with offal, suet, onions and oatmeal; Welsh cakes are from Wales, the Ulster fry from Northern Ireland, and roast beef from England.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7e73444922fe','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Chelsea Flower Show is a famous gardening event held every year.',array['True','False']::text[],'A','Handbook ch. 4 (A modern, thriving society): Many people enjoy gardening; famous events include the Chelsea Flower Show.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:90bb47aa23fa','LIFE_IN_UK'::public.cefr_level,'reading','What kind of constitution does the UK have?',array['A constitution written by the United Nations','One single written document agreed in 1945','One that is not written down in a single document','One Act of Parliament that cannot be changed']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The UK constitution is not written down in any single document; it comes from laws, conventions and court rulings.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9d1faf25b75d','LIFE_IN_UK'::public.cefr_level,'reading','What is the UK''s system of government called?',array['A military government','A one-party state','A parliamentary democracy','An absolute monarchy']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The UK is a parliamentary democracy: the people elect MPs to represent them in Parliament.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f6250ad3eee6','LIFE_IN_UK'::public.cefr_level,'reading','In the UK''s constitutional monarchy, who decides government policy?',array['The Archbishop of Canterbury','The elected government','The senior judges','The monarch alone']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The monarch does not rule the country; the democratically elected government makes policy.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c5add90212f7','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is a ceremonial role of the monarch?',array['Choosing who wins a general election','Leading police investigations','Opening the new session of Parliament each year','Writing new laws']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The monarch has important ceremonial roles, such as the opening of the new parliamentary session each year.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b1373511bb81','LIFE_IN_UK'::public.cefr_level,'reading','Which song is the national anthem of the UK?',array['Jerusalem','God Save the King (or Queen)','Land of Hope and Glory','Rule, Britannia!']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The national anthem is ''God Save the Queen'' — sung as ''King'' when a king reigns — and is played at national occasions.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d5cdc5a4cda7','LIFE_IN_UK'::public.cefr_level,'reading','How many parliamentary constituencies are there in the UK?',array['500','600','650','750']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The country is divided into 650 parliamentary constituencies, each electing one MP.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6f1cb6500ebd','LIFE_IN_UK'::public.cefr_level,'reading','What is the person elected to represent a constituency in the House of Commons called?',array['A Member of Parliament (MP)','A Justice of the Peace','A peer','A councillor']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Each constituency elects a Member of Parliament (MP) to sit in the House of Commons.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5e3a955e5e98','LIFE_IN_UK'::public.cefr_level,'reading','Who keeps order during debates in the House of Commons?',array['The Leader of the Opposition','The Chancellor of the Exchequer','The Prime Minister','The Speaker']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Debates in the House of Commons are chaired by the Speaker, who keeps order and makes sure the rules are followed.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e42c0b5a3ca0','LIFE_IN_UK'::public.cefr_level,'reading','How is the Speaker of the House of Commons chosen?',array['By the monarch','By a public vote','By the Prime Minister','By other MPs in a secret ballot']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Speaker is chosen by other MPs in a secret ballot and is politically neutral.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:0dc8b69d18f8','LIFE_IN_UK'::public.cefr_level,'reading','Since 1958, who has had the power to nominate life peers?',array['The Speaker','The Archbishop of Canterbury','The Lord Chief Justice','The Prime Minister']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Since 1958 the Prime Minister has had the power to nominate peers just for their own lifetime (life peers).',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:57efce8125a4','LIFE_IN_UK'::public.cefr_level,'reading','What does the House of Lords do with new laws proposed by the House of Commons?',array['Examines them in detail and can suggest amendments','Signs them into law without discussion','Permanently blocks any law it dislikes','Sends them to the courts for approval']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The House of Lords checks laws passed by the House of Commons and can suggest amendments, but the Commons can overrule it.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bc1310d3f09d','LIFE_IN_UK'::public.cefr_level,'reading','How often must a UK general election be held?',array['At least every three years','At least every five years','Every ten years','Every year']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): MPs are elected at a general election, which is held at least every five years.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:65ac87045030','LIFE_IN_UK'::public.cefr_level,'reading','What happens if an MP dies or resigns?',array['The seat stays empty until the next general election','The Speaker chooses a replacement','A general election is held across the UK','A by-election is held in their constituency']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): If an MP dies or resigns, there is a fresh election, called a by-election, in their constituency.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e8442a7293c6','LIFE_IN_UK'::public.cefr_level,'reading','Which voting system is used to elect MPs?',array['Single transferable vote','First past the post','Proportional representation','Alternative vote']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): MPs are elected through ''first past the post'': the candidate with the most votes in a constituency wins.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e3e178af2733','LIFE_IN_UK'::public.cefr_level,'reading','What is the minimum age for voting in a UK general election?',array['18','21','16','25']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The present voting age of 18 was set in 1969; you must be 18 or over to vote in general elections.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:31598c086913','LIFE_IN_UK'::public.cefr_level,'reading','What must you do before you can vote in a UK election?',array['Join a political party','Register on the electoral register','Pass a citizenship test','Pay a voting fee']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): To be able to vote in a parliamentary, local or other election, you must have your name on the electoral register.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:803c3a652c4f','LIFE_IN_UK'::public.cefr_level,'reading','Where do people usually go to cast their vote in person?',array['A polling station','A post office counter','A job centre','A magistrates'' court']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Elections are held in polling stations (called polling places in Scotland); you can also apply for a postal vote.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:82b8be96cab3','LIFE_IN_UK'::public.cefr_level,'reading','What is the official report of what is said in Parliament called?',array['The Domesday Book','Hansard','The Gazette','The Electoral Roll']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Proceedings in Parliament are published in Hansard, the official report.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:3cfd19574390','LIFE_IN_UK'::public.cefr_level,'reading','Where is the Prime Minister''s official residence?',array['10 Downing Street','Westminster Abbey','11 Downing Street','Buckingham Palace']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Prime Minister''s official home is 10 Downing Street in central London.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6457dbcf9279','LIFE_IN_UK'::public.cefr_level,'reading','What is the Prime Minister''s country house called?',array['Chequers','Sandringham','Windsor Castle','Balmoral']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Prime Minister also has a country house outside London called Chequers.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6d694c2bc81c','LIFE_IN_UK'::public.cefr_level,'reading','Who appoints the members of the Cabinet?',array['The Speaker','The House of Lords','The voters in a general election','The Prime Minister']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Prime Minister appoints about 20 senior MPs and peers to the Cabinet.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2672908d888d','LIFE_IN_UK'::public.cefr_level,'reading','Which Cabinet minister is responsible for the economy?',array['The Home Secretary','The Foreign Secretary','The Leader of the House','The Chancellor of the Exchequer']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Chancellor of the Exchequer is responsible for the economy.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1571d7e2c299','LIFE_IN_UK'::public.cefr_level,'reading','Which Cabinet minister is responsible for crime, policing and immigration?',array['The Chancellor of the Exchequer','The Home Secretary','The Foreign Secretary','The Secretary of State for Education']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Home Secretary is responsible for crime, policing and immigration.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:3d2ee4e1149a','LIFE_IN_UK'::public.cefr_level,'reading','Which Cabinet minister is responsible for managing relationships with other countries?',array['The Home Secretary','The Chancellor of the Exchequer','The Foreign Secretary','The Secretary of State for Defence']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The Foreign Secretary manages relationships with foreign countries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a0c2c40349cb','LIFE_IN_UK'::public.cefr_level,'reading','Who usually becomes Leader of the Opposition?',array['The Speaker of the House of Commons','The leader of the second-largest party in the House of Commons','The leader of the largest party in the House of Lords','The oldest MP in Parliament']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The second-largest party in the House of Commons is called the opposition; its leader is the Leader of the Opposition.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b79fe5c33112','LIFE_IN_UK'::public.cefr_level,'reading','Who appoints the members of the Shadow Cabinet?',array['The monarch','The Leader of the Opposition','The Prime Minister','The Speaker']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Leader of the Opposition appoints senior opposition MPs to be ''shadow ministers'', forming the Shadow Cabinet.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b00a68d00808','LIFE_IN_UK'::public.cefr_level,'reading','What is the weekly event at which MPs can question the Prime Minister called?',array['Prime Minister''s Questions','The Budget','The State Opening','Question Time in the Lords']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Every week while Parliament is sitting, MPs can put questions to the Prime Minister at Prime Minister''s Questions.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9e730a846675','LIFE_IN_UK'::public.cefr_level,'reading','What is the job of the civil service?',array['To judge criminal cases','To elect the Prime Minister','To campaign for the governing party','To carry out government policy in a politically neutral way']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Civil servants support the government in developing and implementing policies; they are politically neutral.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a6779c0bd0e0','LIFE_IN_UK'::public.cefr_level,'reading','What are pressure and lobby groups?',array['Groups of judges who check new laws','Organisations that try to influence government policy','Committees that count votes at elections','Teams of police officers who control crowds']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Pressure and lobby groups are organisations which try to influence government policy; they play an important role in politics.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:50bce7beee5d','LIFE_IN_UK'::public.cefr_level,'reading','What is an MP who does not represent any political party called?',array['A whip','A shadow minister','An independent','A peer']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): There are a few MPs who do not represent any of the main political parties; they are called independents.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9d61d83294d9','LIFE_IN_UK'::public.cefr_level,'reading','What happens if no party wins a majority of seats in a general election?',array['The monarch governs the country alone','The election is cancelled for ten years','The House of Lords chooses the government','Two parties may join together to form a coalition']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): If no party wins a majority, two parties can join together to form a coalition government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5f061547ddbe','LIFE_IN_UK'::public.cefr_level,'reading','When are local elections for councillors normally held?',array['In January','In November','In August','In May']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Local elections for councillors are held in May every year.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:235174c306f8','LIFE_IN_UK'::public.cefr_level,'reading','Where does the Scottish Parliament sit?',array['Edinburgh','London','Aberdeen','Glasgow']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Scottish Parliament was formed in 1999 and sits in Edinburgh, the capital of Scotland.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7526a0fdbae5','LIFE_IN_UK'::public.cefr_level,'reading','Where is the Welsh Government based?',array['Bangor','London','Swansea','Cardiff']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Welsh Government and the national assembly for Wales are based in Cardiff, the capital city of Wales.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c350b9415a95','LIFE_IN_UK'::public.cefr_level,'reading','Where does the Northern Ireland Assembly sit?',array['Londonderry','Belfast','Armagh','Dublin']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Northern Ireland Assembly sits at Stormont in Belfast.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4acb7ec70b0b','LIFE_IN_UK'::public.cefr_level,'reading','Since which year has there been a Scottish Parliament?',array['1999','1979','2007','1922']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Since 1999 there has been a Scottish Parliament, which sits in Edinburgh.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6daf1ed19fff','LIFE_IN_UK'::public.cefr_level,'reading','Which of these matters is decided by the UK government rather than the devolved administrations?',array['Health in Wales','Defence','Education in Scotland','Agriculture in Northern Ireland']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Policies on defence, foreign affairs and immigration remain with the UK government; areas like education and health are devolved.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:035ba9802ffb','LIFE_IN_UK'::public.cefr_level,'reading','Which statement about UK newspapers is correct?',array['Only one newspaper is allowed in each city','Some newspapers hold political opinions and run campaigns','Newspapers may not report on Parliament','Newspapers must be approved by the government before printing']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The UK has a free press. Proprietors and editors of newspapers may hold strong political opinions and run campaigns.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:43de77be6610','LIFE_IN_UK'::public.cefr_level,'reading','What is the Commonwealth?',array['A military alliance of European countries','A trade union for public workers','A court that hears appeals from the UK','A voluntary association of countries, most of which were once part of the British Empire']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Commonwealth is an association of countries that support each other and work together; membership is voluntary.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:20cc30828b9e','LIFE_IN_UK'::public.cefr_level,'reading','Which organisation drew up the European Convention on Human Rights?',array['The Council of Europe','The Commonwealth','NATO','The United Nations']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Council of Europe created the European Convention on Human Rights, and the UK was one of its early signatories.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:104baea1a361','LIFE_IN_UK'::public.cefr_level,'reading','How many permanent members does the UN Security Council have?',array['Ten','Five','Three','Fifteen']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The UK is one of five permanent members of the UN Security Council.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5596094a2d0d','LIFE_IN_UK'::public.cefr_level,'reading','Which law brought the European Convention on Human Rights into UK law?',array['The Equality Act 1958','The Magna Carta','The Human Rights Act 1998','The Representation of the People Act 1969']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The European Convention on Human Rights is incorporated into UK law by the Human Rights Act 1998.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a9f24fdc00e8','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is an example of a criminal offence?',array['Being in debt to a shop','A dispute with a landlord about repairs','A disagreement about a work contract','Carrying a weapon']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Criminal law covers crimes such as carrying a weapon, drug crime or theft; civil law settles disputes between people.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e6e2b98f450b','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is an example of a civil law matter?',array['Selling tobacco to someone under 18','A dispute about faulty goods bought from a shop','Theft from a shop','Drink-driving']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Civil law is used to settle disputes between individuals or groups, such as consumer rights, housing or employment issues.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e0144e0aa92a','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is a duty of the police?',array['Deciding the sentence in a criminal case','Collecting income tax','Protecting life and property','Writing new laws']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The police protect life and property, prevent disturbances, and prevent and detect crime.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:87fe7ef84d7b','LIFE_IN_UK'::public.cefr_level,'reading','What do Police Community Support Officers (PCSOs) do?',array['Support police officers by patrolling the streets and working with the public','Represent people in court','Judge minor criminal cases','Collect council tax']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): PCSOs support police officers: they patrol the streets, work with the public and support police at crime scenes and major events.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1fd5510072a6','LIFE_IN_UK'::public.cefr_level,'reading','Who sets local police priorities and the force budget in England and Wales?',array['An elected Police and Crime Commissioner','The Speaker of the House of Commons','The local MP','A judge in the Crown Court']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Police and Crime Commissioners (PCCs) are elected and set local police priorities, the budget and appoint the Chief Constable.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:cc84b83e2b74','LIFE_IN_UK'::public.cefr_level,'reading','How can you make a complaint about the police?',array['By telling your local magistrate','By going to a police station or writing to the Chief Constable','Complaints about the police are not allowed','By writing to the monarch']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): You can complain by going to a police station or writing to the Chief Constable of the police force involved.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e6cb0b8597ba','LIFE_IN_UK'::public.cefr_level,'reading','In England and Wales, where are most minor criminal cases dealt with?',array['A magistrates'' court','A County Court','The Crown Court','The Supreme Court']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): In England, Wales and Northern Ireland most minor criminal cases are dealt with in a magistrates'' court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:4d0e1e6d7af1','LIFE_IN_UK'::public.cefr_level,'reading','Who normally decides cases in a magistrates'' court in England and Wales?',array['Unpaid magistrates from the local community','A Police and Crime Commissioner','A judge and a jury of 12','A jury of 15']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Magistrates (Justices of the Peace) are usually unpaid volunteers and do not need legal qualifications.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:bc8b31f82681','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, where are minor criminal offences dealt with?',array['The Crown Court','A County Court','A Justice of the Peace Court','A Youth Court']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): In Scotland, minor criminal offences go to a Justice of the Peace Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:25cdc2ddeac7','LIFE_IN_UK'::public.cefr_level,'reading','In England, Wales and Northern Ireland, where are serious criminal cases tried?',array['In a magistrates'' court, before three magistrates','In the Crown Court, before a judge and jury','In a Youth Court, before a jury','In a County Court, before a single judge']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Serious offences are tried in front of a judge and a jury in a Crown Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:6cfb4cc4186d','LIFE_IN_UK'::public.cefr_level,'reading','How many people sit on a jury in Scotland?',array['10','12','21','15']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): A jury in Scotland has 15 members; in England, Wales and Northern Ireland a jury has 12 members.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1ba2e051c7aa','LIFE_IN_UK'::public.cefr_level,'reading','Who is usually tried in a Youth Court?',array['Young people aged 10 to 17','Students in full-time education','Children under 10','Anyone under 25']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): If an accused person is aged 10 to 17, the case is normally heard in a Youth Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:2a183ccb17ef','LIFE_IN_UK'::public.cefr_level,'reading','What is the small claims procedure?',array['A tax on small businesses','A court for young offenders','An informal way to settle minor disputes without needing a lawyer','A way to appeal against a prison sentence']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The small claims procedure helps people settle minor disputes without spending a lot of money on a lawyer.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:102d7f88646a','LIFE_IN_UK'::public.cefr_level,'reading','Where can you get free, confidential advice on legal and other problems?',array['The Crown Court','Citizens Advice','The House of Lords','HM Revenue & Customs']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Citizens Advice can give free and confidential advice and can help you find a solicitor.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:42928c85adc9','LIFE_IN_UK'::public.cefr_level,'reading','Which organisation collects taxes in the UK?',array['The Bank of England','HM Revenue & Customs (HMRC)','The electoral registration office','The local police force']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Income tax and National Insurance are collected by HM Revenue & Customs (HMRC).',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5bc4ba274436','LIFE_IN_UK'::public.cefr_level,'reading','What do National Insurance contributions help to pay for?',array['State benefits and services such as the state pension and the NHS','Only local libraries and parks','Only the armed forces','The monarch''s private homes']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Money raised from National Insurance contributions pays for state benefits and services such as the state pension and the NHS.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5299f9b54a59','LIFE_IN_UK'::public.cefr_level,'reading','What is the minimum age for driving a car in the UK?',array['18','21','16','17']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): You must be at least 17 years old to drive a car and must have a driving licence.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:defdb44243b1','LIFE_IN_UK'::public.cefr_level,'reading','When must a car have an MOT test?',array['Only before a long journey','Every five years','Only when it is sold','Every year once it is over three years old']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): If your vehicle is over three years old, you must take it for a Ministry of Transport (MOT) test every year.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a47bff4dc07e','LIFE_IN_UK'::public.cefr_level,'reading','What do school governors do?',array['Inspect school buildings for the police','Help set the strategic direction of a school and check its performance','Teach lessons when teachers are ill','Decide pupils'' exam marks']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): School governors set the strategic direction of the school, ensure accountability and monitor and evaluate school performance.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:93e418db20d7','LIFE_IN_UK'::public.cefr_level,'reading','Where can MPs regularly meet people from their constituency?',array['At Prime Minister''s Questions','At local ''surgeries''','At Chequers','At the Crown Court']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Many MPs hold regular local ''surgeries'' where constituents can go in person to talk about issues.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:9d1011c20809','LIFE_IN_UK'::public.cefr_level,'reading','How can members of the public watch debates in the House of Commons?',array['They are never allowed to watch','Only by paying a large fee','Only if they are invited by the monarch','From the public galleries, free of charge']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): You can watch debates from the public galleries in both the House of Commons and the House of Lords; entry is free.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:72ac6bbdaaa5','LIFE_IN_UK'::public.cefr_level,'reading','Which numbers can you call in an emergency to reach the police, fire or ambulance services?',array['123 or 321','999 or 112','100 or 200','101 or 111']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): In an emergency, call 999 or 112 and ask for the police, fire service or ambulance.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d40f2591a9ab','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The UK constitution is not written down in any single document.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The constitution is made up of laws, conventions and court judgments rather than one document.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:a3d203c0f9ac','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Members of the House of Lords are elected by the public.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Members of the House of Lords (peers) are not elected; they are appointed or inherit their seats.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:44c111f89c77','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: MPs are elected using a system called ''first past the post''.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): In each constituency the candidate with the most votes is elected.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:f86f237c88a2','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Speaker supports the government party in debates.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Speaker is politically neutral and keeps order in debates.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:32eb151b317d','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: British citizens aged 18 or over who are registered can vote in general elections.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The voting age is 18, and you must be on the electoral register.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5fcffb78a0d2','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Only people who were born in the UK can vote in UK general elections.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): UK citizens, citizens of the Irish Republic and eligible Commonwealth citizens resident in the UK can vote.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:0c3779e55c4b','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Citizens of the Irish Republic who live in the UK can vote in all public elections.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Adult citizens of the UK, Commonwealth and Irish Republic who are resident in the UK can vote in all public elections.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:c9b544cec2c6','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: All civil servants are replaced when a new party forms the government.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Civil servants are politically neutral and continue in their jobs whichever party is in power.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b93238ee299a','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The monarch can advise, warn and encourage the Prime Minister.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The monarch has regular meetings with the Prime Minister and can advise, warn and encourage, but decisions are made by the government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:d0ed7c2f6b25','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: A jury in Scotland has 12 members.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Juries in Scotland have 15 members; in England, Wales and Northern Ireland they have 12.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:1dff1d8d2013','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Courts can issue Forced Marriage Protection Orders to protect people at risk of a forced marriage.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Forced marriage is a serious abuse of human rights, and courts can make protection orders for people at risk.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:13f09b027983','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Female genital mutilation (FGM) is illegal in the UK.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): FGM is a crime in the UK, as is taking a girl abroad for FGM.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:8c5236178c7b','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: A husband cannot be charged with raping his wife.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Any man who forces a woman to have sex, including her husband, can be charged with rape.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e52c876efb1e','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The UK is a permanent member of the United Nations Security Council.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The UK is one of five permanent members of the UN Security Council.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:0c5853e34bc0','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The European Convention on Human Rights was drawn up by the United Nations.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): It was drawn up by the Council of Europe, not the UN.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:81a91eedafeb','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Cars over three years old must pass an MOT test every year.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Vehicles over three years old need a valid MOT certificate each year.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:026221925808','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: You can drive a car on UK roads from the age of 16.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): You must be at least 17 to drive a car.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:baabb4507002','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Magistrates in England and Wales are usually unpaid and do not need legal qualifications.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Magistrates (JPs) are usually unpaid volunteers from the local community.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b1d0d65667f5','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Police and Crime Commissioners are appointed by the Prime Minister.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Police and Crime Commissioners are elected by the public.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:349b105a5e71','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Many MPs hold local ''surgeries'' where constituents can meet them.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Surgeries let constituents raise issues with their MP in person.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:53b8cb1b0bfd','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Members of the public are not allowed to watch debates in the House of Commons.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The public can watch debates free of charge from the public galleries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b1a65567e745','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: People who are self-employed usually need to complete a self-assessment tax return.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Self-employed people must pay their own tax through self-assessment.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:239d9ab09271','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: It is legal for an employer to refuse someone a job because of their religion.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): UK law prohibits discrimination at work on grounds including religion or belief, sex, race, disability, sexual orientation and age.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:148c79a90d2e','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: A by-election chooses a new MP for a single constituency.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): A by-election is held when an MP dies or resigns.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:ca7851e8b788','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Human Rights Act 1998 removed the European Convention on Human Rights from UK law.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Human Rights Act 1998 incorporated the Convention into UK law.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:72063729065e','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO make up the two Houses of Parliament?',array['The House of Commons and the Supreme Court','The Cabinet and the civil service','The House of Commons and the House of Lords','The House of Lords and the local council']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Parliament has two Houses: the elected House of Commons and the House of Lords.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:7e69bf003682','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO are rights protected by the European Convention on Human Rights?',array['The right to a free house and the right to a car','The right to life and freedom from torture','The right to avoid tax and the right to refuse jury service','The right to carry a weapon and the right to a free car']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Convention protects rights such as the right to life, prohibition of torture, freedom from slavery, liberty and a fair trial.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:971648b1465b','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO must you have to drive a car legally on UK roads?',array['A council tax bill and a passport','A passport and a TV licence','A valid driving licence and motor insurance','A bank account and a library card']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): You must have a valid driving licence, and it is a criminal offence to drive without insurance.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:e3de81be3065','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO services are usually provided by local councils?',array['Passports and immigration control','National Insurance and the armed forces','Rubbish collection and libraries','Defence and foreign policy']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Local authorities provide services such as education, housing, rubbish collection and libraries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:49d668b6920f','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO groups can vote in UK general elections if they are 18 and resident here?',array['Irish citizens and eligible Commonwealth citizens','People aged 16 and tourists','Tourists and visiting students from any country','US citizens and Chinese citizens']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): UK citizens, citizens of the Irish Republic and eligible Commonwealth citizens resident in the UK can vote in general elections.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:41d95aff623b','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO are good ways to help protect the environment?',array['Recycling waste and walking or cycling for short journeys','Using the car for short trips and wasting water','Burning rubbish and throwing away glass','Leaving lights on and driving everywhere']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Recycling, and walking, cycling or using public transport, help reduce pollution; buying local food also helps.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:88efebc75938','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO statements about the Speaker are correct?',array['They lead the government and appoint the Cabinet','They are politically neutral and are chosen by MPs in a secret ballot','They are appointed by the monarch and lead the opposition','They are elected by the public and chair the House of Lords']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Speaker is neutral, chosen by other MPs in a secret ballot, and keeps order in debates.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:b995a48cf1a6','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO can sit in the House of Lords?',array['Life peers and senior bishops of the Church of England','Police and Crime Commissioners and councillors','Magistrates and MPs','MPs and local councillors']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The House of Lords includes life peers, hereditary peers and senior bishops of the Church of England.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:050e3a1df627','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO international organisations is the UK a member of?',array['The United Nations and NATO','The Arab League and NATO','NATO and the Warsaw Pact','The African Union and the United Nations']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The UK is a member of the United Nations, NATO, the Commonwealth and the Council of Europe.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
  ('ai:ai-batch-04:5299b3261222','LIFE_IN_UK'::public.cefr_level,'reading','What is the National Eisteddfod of Wales?',array['The Welsh national parliament','An annual cultural festival, largely in Welsh','A traditional Welsh meal','A Welsh rugby tournament']::text[],'B','Handbook ch. 4 (A modern, thriving society): The National Eisteddfod of Wales is an annual cultural festival which includes music, dancing, art and original performances, largely in Welsh.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-04',null,null,null,null),
